import { test, expect } from "../helpers/test";
import { callJsonRpc, waitForWebRTCReady } from "../helpers";

// The Mini takes only its EDID presets, no custom EDID, so the Video settings
// page must offer exactly the presets that the Mini lists and no field for
// another EDID. edid-presets.spec.ts leaves a "custom" option out of its
// comparison. That the Mini lists exactly the presets generated by
// tools/edid/generate_presets.py is an integration test
// (tools/integration/tests/edid_presets.test.mjs).

test("the Video settings page offers only the Mini's EDID presets", async ({ page }) => {
  test.setTimeout(90_000);

  await page.goto("/settings/video", { waitUntil: "networkidle" });
  // Not ensureRpcReady: its retries reload "/" and would leave this settings route.
  await waitForWebRTCReady(page, 60_000);

  const presets = (await callJsonRpc(page, "getEDIDPresets")) as { name: string; edid: string }[];
  const select = page
    .locator("select")
    .filter({ has: page.locator("option").filter({ hasText: "JetKVM Default" }) });
  await expect(select).toBeVisible();
  const values = await select
    .locator("option")
    .evaluateAll(options => options.map(option => (option as HTMLOptionElement).value));
  expect(
    values.map(v => v.toUpperCase()),
    "the page offers only the presets",
  ).toEqual(presets.map(p => p.edid.toUpperCase()));
  await expect(page.locator("textarea:visible"), "no custom EDID field").toHaveCount(0);
});
